  'Weigh in before workouts': 'Взвешивание перед тренировкой',
  'Asks for your body weight when a workout starts. Off starts the session straight away.': 'Спрашивает ваш вес при начале тренировки. Если выключено, сессия начинается сразу.',
  'No weigh-ins yet. Log your weight to start the curve.': 'Взвешиваний пока нет. Внесите вес, и кривая начнётся.',
  'Music playing on this phone stops during a workout and does not resume by itself.': 'Музыка, играющая на этом телефоне, останавливается во время тренировки и сама не возобновляется.',
  'The end of a rest rings through silent. Music turns down for it and keeps playing.': 'Конец отдыха звучит даже в беззвучном режиме. Музыка ненадолго становится тише и продолжает играть.',
  'The quieter three-beep sound from before 1.3.9, instead of the louder chime.': 'Более тихий звук из трёх сигналов, как до версии 1.3.9, вместо более громкого перезвона.',
  'Export backup (JSON)': 'Экспорт резервной копии (JSON)',
  'Import backup': 'Импорт резервной копии',
  'Auto-backup on changes': 'Автосохранение копии при изменениях',
  'Saves a dated copy to Documents/openGym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.': 'Сохраняет копию с датой в папку «Документы/openGym» после завершения тренировки или редактирования программы и хранит {0} последних. Направьте на эту папку приложение синхронизации или скопируйте файлы вручную.',
  'Reset everything?': 'Сбросить всё?',
  'Reset everything': 'Сбросить всё',
  'Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.': 'Удаляет план, тренировки, вес тела, фото и видео на этом устройстве. Отменить нельзя.',
  'Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.': 'Удаляет план, тренировки, вес тела, фото и видео из профиля на этом сервере и со всех устройств, где выполнен вход. Отменить нельзя.',
  'Sync failed: the server refused the upload as too large. Your changes have not reached the server.': 'Синхронизация не удалась: сервер отклонил загрузку как слишком большую. Ваши изменения не дошли до сервера.',
  'This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.': 'На этом устройстве нет места: изменение на нём не сохранено. Если вы вошли в аккаунт, оно всё равно уйдёт на сервер.',
  'Delete everything': 'Удалить всё',
  'All data reset': 'Все данные сброшены',
  'Backup exported': 'Копия экспортирована',
  'Import backup?': 'Импортировать копию?',
  'This replaces all current data with the backup file.': 'Все текущие данные будут заменены файлом резервной копии.',
  'Backup imported': 'Копия импортирована',
  'Import failed: {0}': 'Импорт не удался: {0}',
  'Tip': 'Совет',
