  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'Ваше имя, данные для входа и всё остальное из вашей учётной записи остаются здесь. Данные других людей никогда не передаются.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'Тренер не врач и не физиотерапевт. Если что-то болит, обратитесь к специалисту.',
