  'min': 'мин',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Тренер подгоняет объём под то время, которое у вас есть, включая отдых между подходами.',
  'What can you train with?': 'С каким оборудованием вы тренируетесь?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Отметьте всё, к чему у вас есть доступ. Если оставить пустым, Тренер использует всю библиотеку.',
  'Anything to work around?': 'Что-то нужно обойти?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Травмы, ноющие суставы, недоступные движения или бытовые ограничения, например тренировка в 6 утра в квартире.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'напр. «капризное левое плечо, без жима штанги над головой»',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Если что-то действительно болит, обратитесь к специалисту. Тренер будет составлять план осторожно, но ставить диагнозы он не умеет.',
