  'Based on your last {0} sessions': 'По вашим последним {0} занятиям',
  'Your plan changed since the Coach looked at it. Suggestions that no longer match are greyed out. Ask for a fresh review to see them again.': 'Ваш план изменился с тех пор, как Тренер его смотрел. Предложения, которые больше не подходят, показаны серым. Запросите новый разбор, чтобы увидеть их снова.',
