  'Could not load': 'Не удалось загрузить',
  'Could not save': 'Не удалось сохранить',
  'Only medians across everyone who shares, never a name, a body weight or a single session. Turning this off removes you from the numbers immediately.': 'Только медианы среди тех, кто делится, никаких имён, веса тела или отдельных сессий. Если выключите, сразу исчезнете из цифр.',
