  'Other': 'Другое',
  'There’s no workout to look at yet. Log one first.': 'Пока нет тренировки для разбора. Сначала запишите одну.',
  'Every planned set done: {0} of {1}.': 'Все запланированные подходы сделаны: {0} из {1}.',
  '{0} of {1} planned sets done.': 'Сделано {0} из {1} запланированных подходов.',
