  '{0} new personal records.': 'Новых личных рекордов: {0}.',
  '{0} minutes is long. Rest periods may be creeping up.': '{0} минут, это долго. Похоже, отдых растягивается.',
  'Top sets logged without an effort rating; add RIR so the next review can read how hard they were.': 'Основные подходы записаны без оценки усилия; добавьте RIR, чтобы следующий разбор понял, насколько было тяжело.',
  'Add the next load step on the main lift.': 'Прибавьте следующий шаг веса в основном движении.',
  'Repeat the same loads and get every set.': 'Повторите те же веса и сделайте все подходы.',
  'Keep the session under an hour and a quarter.': 'Держите сессию в пределах часа с четвертью.',
  'A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.': 'Чистая тренировка: всё по плану сделано, веса удержаны. Именно так прогресс выглядит изнутри: неприметно, раз за разом.',
  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': 'Большая часть работы сделана. Один-два подхода не дотянули, один раз это нормально. Сигналом это станет, только если те же подходы не выйдут и в следующий раз.',
