  '{0} workout and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '{0} тренировка и {1} взвешивание были записаны на этом устройстве без входа. Добавьте их в профиль или оставьте профиль ровно таким, как на сервере.',
  '{0} workout and {1} weigh-ins were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '{0} тренировка и {1} взвешиваний были записаны на этом устройстве без входа. Добавьте их в профиль или оставьте профиль ровно таким, как на сервере.',
  '{0} workouts and {1} weigh-in were logged on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '{0} тренировок и {1} взвешивание были записаны на этом устройстве без входа. Добавьте их в профиль или оставьте профиль ровно таким, как на сервере.',
