  'Server error (HTTP {0})': 'Ошибка сервера (HTTP {0})',
  'Your server answered with an error (HTTP {0}). Your changes are kept here.': 'Ваш сервер ответил ошибкой (HTTP {0}). Ваши изменения остаются здесь.',
