  'Your server no longer accepts this browser. Your changes are kept here.': 'Ваш сервер больше не принимает этот браузер. Ваши изменения остаются здесь.',
  'This phone is no longer paired with your server. Your changes are kept here.': 'Этот телефон больше не сопряжён с вашим сервером. Ваши изменения остаются здесь.',
  'The server refuses this phone': 'Сервер отклоняет этот телефон',
  'Your server no longer accepts this phone. Your changes are kept here.': 'Ваш сервер больше не принимает этот телефон. Ваши изменения остаются здесь.',
