  'Some changes on this device have not reached your server.': 'Некоторые изменения на этом устройстве ещё не дошли до вашего сервера.',
  'Try again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Повторите попытку или сначала экспортируйте резервную копию. Если всё равно продолжить, копия этих изменений останется на этом устройстве, пока оно снова не подключится к этому серверу с этим аккаунтом. Тогда они будут добавлены обратно.',
  'Syncing…': 'Синхронизация…',
  'Try again': 'Повторить',
  'Last synced: {0}': 'Последняя синхронизация: {0}',
  'Not synced with this server yet': 'Ещё не синхронизировано с этим сервером',
  'Server & sync': 'Сервер и синхронизация',
  'Signed in as {0}': 'Вы вошли как {0}',
  'Sync now': 'Синхронизировать сейчас',
  'Your changes are kept here, and merged into your account once it is paired again.': 'Ваши изменения остаются здесь и будут объединены с вашим аккаунтом, как только телефон снова будет сопряжён.',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'Ваши изменения остаются здесь и будут объединены с вашим аккаунтом, как только вы снова войдёте.',
  'Changes kept for {0}': 'Сохранённые изменения для {0}',
  'Added back when this device connects as that account again.': 'Будут добавлены обратно, когда это устройство снова подключится с этим аккаунтом.',
  'The changes your server has not seen are kept on this device, and added back when it connects as this account again.': 'Изменения, которых ещё нет на вашем сервере, сохраняются на этом устройстве и будут добавлены обратно, когда оно снова подключится с этим аккаунтом.',
  'This phone switches back to local-only and its copy of your account is removed. First it checks that your server has every change. If not, you choose what happens to them.': 'Этот телефон вернётся в локальный режим, а копия вашего аккаунта будет с него удалена. Сначала проверяется, что на вашем сервере есть все изменения. Если нет, вы сами решаете, что с ними делать.',
  'Your data is removed from this browser; your profile on the server keeps it. First it checks that the server has every change. If not, you choose what happens to them.': 'Ваши данные будут удалены из этого браузера; ваш профиль на сервере их сохранит. Сначала проверяется, что на сервере есть все изменения. Если нет, вы сами решаете, что с ними делать.',
  'Signs this profile out on every device, including this one. Phones paired with it are disconnected and have to be paired again. Your passkeys keep working, so you can sign in with them again anytime.': 'Выполняет выход из этого профиля на всех устройствах, включая это. Сопряжённые с ним телефоны отключаются, и их нужно будет сопрячь заново. Ваши ключи доступа продолжают работать, так что войти с ними снова можно в любое время.',
