  'The server cannot be reached': 'Сервер недоступен',
  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': 'Ваш сервер недоступен. Изменения сохранены на этом устройстве и синхронизируются, как только он снова ответит.',
  'Your server can’t be reached. Showing the last copy synced with it.': 'Ваш сервер недоступен. Показана последняя копия, синхронизированная с ним.',
  'Server address unknown': 'Адрес сервера неизвестен',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Выполните сопряжение заново или сначала экспортируйте резервную копию. Если всё равно продолжить, копия этих изменений останется на этом устройстве, пока оно снова не подключится к этому серверу с этим аккаунтом. Тогда они будут добавлены обратно.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Войдите снова или сначала экспортируйте резервную копию. Если всё равно продолжить, копия этих изменений останется на этом устройстве, пока оно снова не подключится к этому серверу с этим аккаунтом. Тогда они будут добавлены обратно.',
  'Every exercise in this workout': 'Все упражнения этой тренировки',
  'No sets are left in this workout, so there is nothing to save. Delete it from your history?': 'В этой тренировке не осталось ни одного подхода, сохранять нечего. Удалить её из истории?',
  // --- a custom exercise's own photo, GIF or video, and its link ---
  'Photo, GIF or video': 'Фото, GIF или видео',
  'Optional. A picture makes it easier to spot in a list.': 'Необязательно. С картинкой его проще найти в списке.',
  'Add': 'Добавить',
  'Change': 'Заменить',
  'Video or guide link (optional)': 'Ссылка на видео или руководство (необязательно)',
  'That link is not a web address': 'Эта ссылка не веб-адрес',
  'Watch video': 'Смотреть видео',
  'Open link': 'Открыть ссылку',
  'Plays from YouTube, and only once you tap': 'Играет с YouTube, и только после нажатия',
  'Opens in YouTube': 'Откроется в YouTube',
  'That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.': 'Этот тип файла не поддерживается. Выберите фото, GIF или видео MP4, MOV или WebM.',
  'That file is too big. Max {0} MB.': 'Файл слишком большой. Максимум {0} МБ.',
  'That video is too long. Max {0} seconds.': 'Видео слишком длинное. Максимум {0} секунд.',
  'That photo is too large to process on this device.': 'Это фото слишком большое, чтобы обработать его на этом устройстве.',
  'You’re offline. Try again once you’re back online.': 'Вы офлайн. Попробуйте ещё раз, когда появится интернет.',
  'This browser cannot read that file.': 'Этот браузер не может прочитать файл.',
  'There is no room left on this device for that file.': 'На этом устройстве не осталось места для этого файла.',
  'This video may not play on every device. MP4 (H.264) plays everywhere.': 'Это видео может воспроизводиться не на всех устройствах. MP4 (H.264) работает везде.',
  'Your photo and video space on the server is full ({0} of {1} MB).': 'Место для фото и видео на сервере закончилось ({0} из {1} МБ).',
  'The server refused the file as too large.': 'Сервер отклонил файл как слишком большой.',
  'Kept on this device only. Export with photos & videos keeps a copy.': 'Хранится только на этом устройстве. Экспорт с фото и видео сохранит копию.',
  'Your server does not store photos and videos yet.': 'Ваш сервер пока не хранит фото и видео.',
  'This browser cannot store photos or videos here.': 'Этот браузер не может хранить здесь фото и видео.',
  'Photos & videos': 'Фото и видео',
  '{0} of {1} MB used on your server': 'Занято на вашем сервере: {0} из {1} МБ',
  '{0} waiting to upload': 'Ожидают загрузки: {0}',
  'Export with photos & videos (.zip)': 'Экспорт с фото и видео (.zip)',
  'Without photos and videos': 'Без фото и видео',
  'Name it and pick a body part. It works just like any other exercise.': 'Дайте название и выберите часть тела. Упражнение работает как любое другое.',
  'name + body part, and a photo or video if you like': 'название + часть тела и, по желанию, фото или видео',
