  // --- AI Coach: why a job failed or was refused (lib/coach-api.js JOB_ERRORS, BYOK_ERRORS) ---
  'The Coach isn’t set up on this instance.': 'Тренер не настроен на этом сервере.',
  'The Coach is taking a rest day. Try again tomorrow.': 'У тренера выходной. Попробуйте ещё раз завтра.',
  'The Coach took too long and gave up.': 'Тренер думал слишком долго и сдался.',
  'The Coach couldn’t sign in to its provider. The instance owner needs to check its setup.': 'Тренеру не удалось войти в аккаунт провайдера. Владельцу сервера нужно проверить настройки.',
  'The Coach isn’t installed properly on this instance.': 'Тренер неправильно установлен на этом сервере.',
  'The Coach couldn’t run. The instance owner needs to check its setup.': 'Тренеру не удалось запуститься. Владельцу сервера нужно проверить настройки.',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': 'Тренер упёрся в лимит своего ИИ-провайдера. Попробуй позже, а если не поможет, владельцу сервера нужно проверить тариф или ключ.',
  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': 'ИИ-провайдер Тренера отклонил формат запроса. Владельцу сервера нужно попробовать другую модель.',
  'The Coach’s AI provider is having an outage. Try again in a little while.': 'У ИИ-провайдера Тренера сбой. Попробуй ещё раз чуть позже.',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': 'Тренер не смог связаться со своим ИИ-провайдером. Владельцу сервера нужно проверить адрес и сеть.',
  'The Coach answered with something the app couldn’t use.': 'Тренер прислал ответ, которым приложение не может воспользоваться.',
  'The server restarted while the Coach was thinking.': 'Сервер перезапустился, пока тренер думал.',
  'The Coach couldn’t read your training data.': 'Тренеру не удалось прочитать ваши данные о тренировках.',
  'The Coach is switched off on this instance for safety reasons.': 'Тренер отключён на этом сервере из соображений безопасности.',
  'Something went wrong on the server.': 'На сервере что-то пошло не так.',
  'Your AI provider rejected the key on this phone. Check it under Settings → AI Coach.': 'Ваш провайдер ИИ отклонил ключ на этом телефоне. Проверьте его в Настройках → ИИ-тренер.',
  'The Coach isn’t set up on this phone. Check Settings → AI Coach.': 'Тренер не настроен на этом телефоне. Проверьте Настройки → ИИ-тренер.',
  'Your AI provider couldn’t answer.': 'Ваш провайдер ИИ не смог ответить.',
  'Something went wrong on this phone.': 'На этом телефоне что-то пошло не так.',
  'Coach week': 'Неделя тренера',
  'Your loop': 'Ваш круг',
  // Rotation (lib/rotation.js) — an in-app alternative to the weekday plan.
  'Rotation': 'Ротация',
  'Fixed Week': 'Фиксированная неделя',
  'Externally managed': 'Управляется извне',
  'Add routine to the rotation': 'Добавить программу в ротацию',
  'Add to the rotation': 'Добавить в ротацию',
  'No rotation yet. Add routines in the order you want to train them. The first one you haven’t logged stays up next.': 'Ротации пока нет. Добавляйте программы в том порядке, в котором хотите их тренировать. Первая незаписанная всегда идёт следующей.',
  'Use this rotation': 'Использовать эту ротацию',
  'Use this rotation?': 'Использовать эту ротацию?',
  'Your own loop gets replaced.': 'Ваш собственный круг будет заменён.',
  'Your coach gives up control of this week: openGym owns the queue from here on and repeats these sessions by itself once they are all done. A new week from the coach’s app would replace this rotation.': 'Ваш тренер отказывается от контроля над этой неделей: очередь с этого момента принадлежит openGym, который сам повторяет эти сессии, как только они все завершены. Новая неделя из приложения тренера заменит эту ротацию.',
  'Start new pass': 'Начать новый проход',
  'This rotation couldn’t be read. Another device may have written it.': 'Не удалось прочитать эту ротацию. Возможно, она была записана с другого устройства.',
  'Discard it': 'Отменить её',
  'Use Fixed Week': 'Использовать фиксированную неделю',
  'No rotation yet. Add routines to it in Plan.': 'Ротации пока нет. Добавьте в неё программы в разделе «План».',
