  '{0} photos or videos have not reached your server yet.': { one: '{0} фото или видео ещё не дошло до вашего сервера.', few: '{0} фото или видео ещё не дошли до вашего сервера.', many: '{0} фото или видео ещё не дошли до вашего сервера.' },
  'Its {0} photos or videos are deleted with it.': { one: 'Вместе с ней удалится {0} фото или видео.', few: 'Вместе с ней удалятся {0} фото или видео.', many: 'Вместе с ней удалятся {0} фото или видео.' },
  'Its {0} photos or videos move to the new workout.': { one: 'Её {0} фото или видео перейдёт к новой тренировке.', few: 'Её {0} фото или видео перейдут к новой тренировке.', many: 'Её {0} фото или видео перейдут к новой тренировке.' },
