  '{0} sets become {1}: one on each side, {2}s held every time.': { one: '{0} подход превращается в {1}: по одному на каждую сторону, каждый раз удержание {2} с.', few: '{0} подхода превращаются в {1}: по одному на каждую сторону, каждый раз удержание {2} с.', many: '{0} подходов превращаются в {1}: по одному на каждую сторону, каждый раз удержание {2} с.' },
  'For side planks, single-arm holds and the like. Trains each side on its own.': 'Для боковой планки, удержаний одной рукой и подобного. Каждая сторона тренируется отдельно.',
