  'Back to a fixed week?': 'Вернуться к фиксированной неделе?',
  'The loop stops. Your weekdays stay as they are, and the loop is saved for later.': 'Круг останавливается. Ваши дни недели остаются как есть, а круг сохраняется на потом.',
  'Routines in a loop. Whatever is next stays next until you train it, whatever the day.': 'Программы по кругу. Следующая остаётся следующей, пока вы её не сделаете, в любой день.',
  'The same routines on the same weekdays, every week.': 'Одни и те же программы в одни и те же дни, каждую неделю.',
  'How you train': 'Как вы тренируетесь',
  'Want two routines on one day? Tap the day and pick both.': 'Две программы в один день? Нажмите на день и выберите обе.',
  'The loop': 'Круг',
