  // --- Coach: AI data sharing ---
  'AI data sharing': 'Передача данных ИИ',
  'Allow': 'Разрешить',
  'Allowed {0}': 'Разрешено {0}',
  'Anything you type to the Coach': 'Всё, что вы пишете тренеру',
  'Change your mind anytime under AI data sharing in the Coach menu.': 'Передумать можно в любой момент: меню тренера, раздел «Передача данных ИИ».',
  'Nothing allowed yet': 'Пока ничего не разрешено',
  'Okay, nothing was sent.': 'Хорошо, ничего не отправлено.',
  'Send your training to {0}?': 'Отправить ваши тренировки в {0}?',
  'The Coach asks before anything leaves.': 'Тренер спрашивает, прежде чем что-то отправить.',
  'Through your server': 'Через ваш сервер',
  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': 'Чтобы ответить, тренер отправляет это через ваш сервер openGym в {0}, сторонний ИИ-сервис, который выбрал администратор вашего сервера:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'Чтобы ответить, это устройство отправляет это напрямую в {0}, сторонний ИИ-сервис, с вашим API-ключом:',
  'Who may see your training': 'Кто может видеть ваши тренировки',
  'Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.': 'Кому тренер может отправлять ваши тренировки с этого устройства. Если отозвать согласие, тренер спросит снова в следующий раз. Модели в вашей собственной сети спрашивать не нужно.',
  'With your API key': 'С вашим API-ключом',
