  'Your answers to the Coach: goal, days, equipment, limits and injuries': 'Ваши ответы тренеру: цель, дни, инвентарь, ограничения и травмы',
  'Your body weight and goal weight': 'Ваш вес и целевой вес',
  'Your data, your call': 'Ваши данные, ваше решение',
  'Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.': 'Имя, e-mail и вход остаются здесь. {0} обрабатывает остальное по своим правилам конфиденциальности.',
