  'Apple Watch': 'Apple Watch',
  'Weight': 'Вес',
  'Send workouts to the watch': 'Отправлять тренировки на часы',
  'Open on the watch': 'Открывать на часах',
  'Start a workout on the phone and openGym pops up on your wrist.': 'Начни тренировку на телефоне, и openGym появится у тебя на запястье.',
  'Not allowed': 'Не разрешено',
  'Turn on Apple Health and the watch measures your heart rate for every set.': 'Включи Apple Здоровье, и часы будут мерить пульс в каждом подходе.',
  'Tap the wrist when a rest is over': 'Касание запястья в конце отдыха',
  'No Apple Watch paired with this iPhone': 'К этому iPhone не подключены Apple Watch',
  'openGym is not on your Apple Watch yet. Install it in the Watch app.': 'openGym ещё нет на ваших Apple Watch. Установите его в приложении Watch.',
  'openGym is on your Apple Watch': 'openGym установлен на ваших Apple Watch',
  'Last heard from the watch: {0}': 'Последняя связь с часами: {0}',
  'The watch hasn’t checked in yet. Open openGym on it once.': 'Часы ещё не выходили на связь. Откройте на них openGym один раз.',
  'Not allowed on the watch. Allow it in the Health app on your iPhone.': 'На часах не разрешено. Разрешите в приложении «Здоровье» на iPhone.',
  'Heart rate during the workout and next to each set, and the workout saved to Apple Health. The watch asks once.': 'Пульс во время тренировки и рядом с каждым подходом, тренировка сохраняется в «Здоровье». Часы спросят один раз.',
  'Apple Health': 'Apple Здоровье',
  'Write to Apple Health': 'Записывать в Apple Здоровье',
  'Open Apple Health': 'Открыть Apple Здоровье',
  'Workouts and weigh-ins go to Apple Health when you finish or change them.': 'Тренировки и взвешивания попадают в Apple Здоровье, когда вы их завершаете или меняете.',
  'Writing to Apple Health': 'Запись в Apple Здоровье',
  'Apple Health permission not granted': 'Разрешение Apple Здоровье не выдано',
  'Could not write to Apple Health': 'Не удалось записать в Apple Здоровье',
  'Could not remove it from Apple Health': 'Не удалось удалить из Apple Здоровье',
  'Stop writing to Apple Health?': 'Перестать записывать в Apple Здоровье?',
  'What openGym already wrote can stay in Apple Health as your data, or be removed from it.': 'То, что openGym уже записал, может остаться в Apple Здоровье как ваши данные или быть удалено.',
  'Your workouts in Apple Health': 'Ваши тренировки в Apple Здоровье',
  'openGym can save every workout and weigh-in to Apple Health, and your Apple Watch can show your heart rate while you lift.': 'openGym может сохранять каждую тренировку и взвешивание в Apple Здоровье, а Apple Watch покажет пульс прямо во время подходов.',
  'Workouts and weigh-ins saved to Apple Health': 'Тренировки и взвешивания в Apple Здоровье',
  'Heart rate per set on your Apple Watch': 'Пульс по подходам на Apple Watch',
  'AirPods Pro 3 or Powerbeats Pro 2 in? Your iPhone measures the heart rate for every set, unless your Apple Watch is already on it.': 'AirPods Pro 3 или Powerbeats Pro 2 в ушах? iPhone измерит пульс в каждом подходе, если этим уже не занимаются Apple Watch.',
  'Switch it off anytime in Settings': 'Можно выключить в любой момент в Настройках',
  'You can change it anytime in Settings.': 'Это можно изменить в любой момент в Настройках.',
  'Last PR': 'Последний рекорд',
  'Workout running': 'Тренировка идёт',
  'Set {0} of {1}': 'Подход {0} из {1}',
  'All sets done': 'Все подходы сделаны',
  'Log set': 'Записать подход',
  'Next exercise': 'Следующее упражнение',
  'Skip rest': 'Пропустить отдых',
  'Open openGym for the next set': 'Откройте openGym для следующего подхода',
  'On the watch': 'На часах',
  'Fewer things, bigger numbers. Pick what helps you mid-set.': 'Меньше лишнего, крупнее цифры. Оставьте то, что помогает посреди подхода.',
  'Exercise animation': 'Анимация упражнения',
  'Heart rate': 'Пульс',
  'Time so far': 'Прошло времени',
  'Calories': 'Калории',
  'Next exercise during the rest': 'Следующее упражнение во время отдыха',
  'Ring': 'Кольцо',
  'Countdown only': 'Только отсчёт',
  // --- your bars + warm-up rest default (Discord) ---
  'Your bars': 'Твои грифы',
  'Set the bar once for every exercise of a type.': 'Задай гриф один раз для всех упражнений одного типа.',
  'Your bar for this type, set in Your bars.': 'Твой гриф для этого типа, задан в «Твои грифы».',
  'What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.': 'Сколько весят грифы в твоём зале. Каждое упражнение с этим грифом считает блины от него, если ты не задал ему свой. Записанные веса остаются общими.',
  'Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.': 'Большинство упражнений в библиотеке используют «{0}», некоторые «{1}». Чтобы короткий гриф был везде, задай оба.',
  'Back to the standard bars': 'Вернуть стандартные грифы',
  'Standard bars. Tap if yours are lighter.': 'Стандартные грифы. Нажми, если твои легче.',
  'The last warm-up still gets the full rest before your first work set.': 'Последний разминочный подход всё равно получает полный отдых перед первым рабочим.',
  // --- Coach intake: days and session wheels ---
  'Days per week': 'Дней в неделю',
  'Hours': 'Часы',
  'h': 'ч',
  // --- import with no account: workouts on this device ---
