  "Records": "Рекорды",
  "Schedule says when, Routines says what. Build your own or grab a starter plan.": "Расписание говорит когда, Программы говорят что. Соберите свои или возьмите стартовый план.",
  "Search thousands of exercises in your language. Star your favourites and they float to the top.": "Тысячи упражнений на вашем языке. Отметьте любимые звёздочкой, и они будут сверху.",
  "See which muscles got the work and which still need rest. Tap one for details.": "Смотрите, какие мышцы поработали, а каким ещё нужен отдых. Нажмите на мышцу для деталей.",
