  "Swipe a set": "Смахните подход",
  "Swipe a set sideways to copy or remove it. Its number opens even more.": "Смахните подход в сторону, чтобы скопировать или удалить. Его номер открывает ещё больше.",
  "The big Start button": "Большая кнопка Старт",
  "The little body shows what each day works, so leg day can’t hide.": "Маленькое тело показывает, что качает каждый день, так что день ног не спрячется.",
  "The rest timer starts by itself. Add time, or skip it if you feel heroic.": "Отдых запускается сам. Добавьте время или пропустите, если чувствуете себя героем.",
  "The ⋯ menu": "Меню ⋯",
  "Theme, accent colour and what Home shows.": "Тема, цвет акцента и что показывает Главная.",
  "This one is pretend, nothing gets saved. Each row is a set: weight, then reps. Tap a number to change it.": "Это понарошку, ничего не сохранится. Каждая строка это подход: вес, затем повторы. Нажмите на число, чтобы изменить.",
  "Tick it off": "Отметьте",
  "Today at a glance": "Сегодня коротко",
  "Today’s session lives here. One tap and you’re lifting. On a rest day it says so, no guilt trip.": "Здесь тренировка на сегодня. Одно касание, и вперёд. В день отдыха так и написано, без угрызений.",
  "Train on fixed weekdays, or run your routines in a loop where the next one waits for you.": "Тренируйтесь в фиксированные дни или гоняйте программы по кругу: следующая вас дождётся.",
  "Want a 1-minute tour?": "Минутный тур?",
  "Week or rotation": "Неделя или ротация",
