  "This one lives in the openGym phone app: Apple Health on iPhone, Health Connect on Android.": "Это живёт в приложении openGym на телефоне: Apple Health на iPhone, Health Connect на Android.",
  "Webhooks are sent by your own openGym server, so they need one. Connect this device to it in Account.": "Вебхуки отправляет твой собственный сервер openGym, так что он нужен. Подключи это устройство в разделе «Аккаунт».",
  "Webhooks are off on this server. Add INTEGRATIONS=webhook to its .env and restart it.": "На этом сервере вебхуки выключены. Добавь INTEGRATIONS=webhook в его .env и перезапусти.",
  "The MCP server runs next to your own openGym server and reads your data there.": "Сервер MCP работает рядом с твоим сервером openGym и читает данные там.",
