  "A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.": "Ссылка на «{0}». Друг нажимает на неё и добавляет в свой openGym. Тренировка едет внутри ссылки, без сервера посередине.",
  "Include my weights": "Добавить мои веса",
