  // --- Your year in openGym (lib/wrapped-cards.js, components/Wrapped.jsx) ---
  "Mostly in the morning. The early bird gets the barbell.": "Чаще всего утром. Кто рано встаёт, тому штанга подаёт.",
  "Mostly around lunch. Who needs a lunch break anyway?": "Чаще всего в обед. Кому вообще нужен обеденный перерыв?",
  "Mostly in the afternoon. The sweet spot.": "Чаще всего днём. Золотая середина.",
  "Mostly in the evening. Work, then work out.": "Чаще всего вечером. Сначала работа, потом тренировка.",
  "Mostly late at night. The gym is all yours.": "Чаще всего поздно ночью. Весь зал твой.",
  "Early bird": "Ранняя пташка",
  "Most of your sessions started before 9. The sun was still catching up.": "Большинство твоих тренировок начиналось до 9. Солнце едва поспевало.",
  "Night owl": "Ночная сова",
  "Most of your sessions started after 8 pm. The quiet gym is your gym.": "Большинство твоих тренировок начиналось после 20:00. Тихий зал и есть твой зал.",
  "Leg-day loyalist": "Верность дню ног",
  "You never skipped leg day. Stairs fear you.": "Ни одного пропущенного дня ног. Лестницы тебя боятся.",
  "Clockwork": "Как часы",
  "Week after week after week. Your calendar knows your name.": "Неделя за неделей за неделей. Твой календарь знает тебя по имени.",
  "Record breaker": "Рекордсмен",
  "So many new bests, your trophy shelf needs a trophy shelf.": "Столько новых рекордов, что твоей полке для кубков нужна своя полка для кубков.",
  "Weekend warrior": "Воин выходного дня",
  "Saturdays and Sundays are for lifting. Brunch can wait.": "Суббота и воскресенье созданы для железа. Бранч подождёт.",
  "Cardio comet": "Кардио-комета",
  "Your heart is in great shape. Literally.": "Твоё сердце в отличной форме. В прямом смысле.",
  "In it for the long haul": "Всерьёз и надолго",
  "Long sessions, no rush. The gym is basically your second home.": "Долгие тренировки без спешки. Зал практически твой второй дом.",
  "In and out": "Быстро и чётко",
  "Short, sharp sessions. Efficiency is your love language.": "Короткие, чёткие тренировки. Твой язык любви: эффективность.",
  "Explorer": "Исследователь",
  "So many different exercises, boredom never stood a chance.": "Столько разных упражнений, что у скуки не было ни шанса.",
  "Upper-body enthusiast": "Фанат верха тела",
  "Chest, shoulders, arms. The mirror approves.": "Грудь, плечи, руки. Зеркало одобряет.",
  "Steady and sure": "Ровно и уверенно",
