  "Use this photo": "Взять это фото",
  "Zoom": "Масштаб",
  "Missed plan": "План пропущен",
  "Open this day": "Открыть этот день",
  "Planned, not trained. Any other day this week still counts.": "Запланировано, но без тренировки. Любой другой день этой недели ещё засчитается.",
  "Planned, not trained. Any workout that week would have counted.": "Запланировано, но без тренировки. Засчиталась бы любая тренировка на той неделе.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "Запланировано, но без тренировки. Не страшно: ты тренировался в другой день, так что неделя засчитана.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "1 заморозка в запасе, даётся каждые 4 недели с тренировками. Две пропущенные недели подряд обрывают серию.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "До 2 заморозок в запасе, по одной каждые 4 недели с тренировками. Можно прикрыть даже две пропущенные недели подряд.",
  "Change the freeze rule": "Изменить правило заморозок",
  "Every 4th week you train earns a freeze. You can bank 1.": "Каждая 4-я неделя с тренировками даёт заморозку. Можно копить 1.",
  "Every week counts. Miss one and the streak starts over.": "Каждая неделя на счету. Пропустил одну, и серия начинается заново.",
  "From now on: {0}.": "Теперь: {0}.",
  "From the week of {0} on: {1}.": "С недели {0}: {1}.",
  "Generous": "Щедрое",
  "Gentle": "Мягкое",
  "How forgiving should your week streak be?": "Насколько снисходительной будет твоя недельная серия?",
  "How strict should your streak be?": "Насколько строгой будет твоя серия?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Пропустил неделю? Заморозка её прикроет: серия идёт дальше, просто эта неделя ничего не добавляет. Две пропущенные недели подряд, и серия начнётся заново.",
  "No freezes": "Без заморозок",
  "No freezes on your rule. Every week counts.": "В твоём правиле нет заморозок. Каждая неделя на счету.",
  "No freezes on your rule: a week without a workout starts it over.": "В твоём правиле нет заморозок: неделя без тренировки, и серия начинается заново.",
  "No workout, and your rule has no freezes, so the streak started over.": "Тренировки не было, а заморозок в твоём правиле нет, так что серия началась заново.",
  "Weeks already counted stay as they are.": "Уже посчитанные недели останутся как есть.",
  "You can change it later in Settings. A change counts from then on.": "Это можно изменить позже в настройках. Изменение действует с этого момента.",
  "Your rule right now: {0}.": "Твоё правило сейчас: {0}.",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "Серия считает недели хотя бы с одной тренировкой. Заморозки могут прикрыть случайно пропущенную неделю.",
  "{0} since the week of {1}.": "{0} с недели {1}.",
  "This phone has no print service. Turn one on in its settings and try again.": "На этом телефоне нет службы печати. Включи её в настройках и попробуй ещё раз.",
