  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Это видно всем на этом сервере: любой, у кого здесь есть аккаунт, может это посмотреть, попробовать и скопировать. Твоё имя и дата всегда идут вместе с этим. Делись только своим: тем, что ты сделал, записал или вправе передать дальше. Картинки и анимации упражнений из встроенной библиотеки лицензированы, и делиться ими нельзя никогда. Перестать делиться можно в любой момент; копии, которые другие уже взяли, останутся у них.",
