  "The token {0} was revoked": "Токен {0} отозван",
  "The token {0} changed {1}": "Токен {0} изменил: {1}",
  "A token lets one program, like an AI assistant, see or change only what you tick. Never more than you can, and only your own profile.": "Токен даёт одной программе, например ИИ-ассистенту, видеть или менять только то, что ты отметишь. Никогда больше, чем можешь ты, и только твой профиль.",
  "API token": "API-токен",
  "API tokens": "API-токены",
  "Add it as a custom connector in your AI assistant, with a token from below.": "Добавь его в ИИ-ассистенте как свой коннектор, вместе с токеном ниже.",
  "After a year": "Через год",
  "After {0} days": "Через {0} дн.",
  "Copy it now: this is the only time openGym shows it. Treat it like a password.": "Скопируй его сейчас: openGym показывает его только один раз. Обращайся с ним как с паролем.",
  "Ends": "Истекает",
  "Every program using one stops getting in right away.": "Каждая программа с таким токеном сразу теряет доступ.",
  "For AI assistants over MCP, planners and scripts. Each sees only what you tick.": "Для ИИ-ассистентов через MCP, планировщиков и скриптов. Каждый видит только то, что ты отметишь.",
