  "A buzz for each phase": "Вибрация на каждую фазу",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "Копия всего раз в день в вашей собственной папке: Nextcloud, ownCloud, NAS, что угодно, что говорит на WebDAV. Ваш сервер, и больше ничей.",
  "A sound for each kind of rest": "Свой звук для каждого вида отдыха",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "Галочка на каждом дне с тренировкой, и сколько было подходов. Видите только вы, как и план.",
