  "Calendar feed": "Календарная подписка",
  "Calendar feed off": "Календарная подписка выключена",
  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "Кардио уходит тем, чем было: пробежка, заезд, гребля. Силовые как «Силовая тренировка», с каждым подходом в описании.",
  "Change server or password": "Сменить сервер или пароль",
  "Check the connection": "Проверить подключение",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "Подключите Strava один раз из openGym в браузере, войдя на свой сервер. Дальше тренировки отправляет сервер, на каком бы устройстве вы их ни записывали.",
  "Connected. Your first backup goes up now.": "Подключено. Первая копия уже в пути.",
  "Disconnect Strava?": "Отключить Strava?",
  "Disconnect WebDAV?": "Отключить WebDAV?",
  "Explosive lift (X)": "Взрывной подъём (X)",
  "Folder address": "Адрес папки",
  "Get set": "Приготовьтесь",
  "Know from your pocket whether to stay put, go back to the top of the superset or move on.": "Понимайте прямо по карману: остаться на месте, вернуться к началу суперсета или идти дальше.",
  "Last backup {0}": "Последняя копия {0}",
