  "Two happy notes after the tick, when sounds are on.": "Две радостные ноты после отметки, когда звук включён.",
  "Type a time like 25:00 or 1:45:00.": "Введи время, например 25:00 или 1:45:00.",
  "U.S. Navy tape method. Waist at the navel, neck below the larynx.": "Метод сантиметровой ленты ВМС США. Талия на уровне пупка, шея под гортанью.",
  "Under the next set: its share of your best e1RM and the reps a record needs.": "Под следующим подходом: его доля от твоего лучшего e1RM и сколько повторений нужно для рекорда.",
