  "{0} more reps for a record at this weight": {"one": "Ещё {0} повторение до рекорда с этим весом", "few": "Ещё {0} повторения до рекорда с этим весом", "many": "Ещё {0} повторений до рекорда с этим весом", "other": "Ещё {0} повторения до рекорда с этим весом"},
  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "В этой версии openGym нет связи с Garmin: часть Garmin не открыта. В версиях из App Store, Google Play и GitHub она есть.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "На этом телефоне нет Garmin Connect. Установи его, подключи там часы и возвращайся сюда.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Garmin Connect нужно обновить, прежде чем openGym сможет общаться с часами.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Не удалось связаться с Garmin Connect. Попробуй чуть позже.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Выбери свои Garmin в Garmin Connect, и тренировки появятся на запястье.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect пока не знает ни одних часов. Сначала подключи свои там.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym стоит на твоих Garmin. Подходы, записанные на запястье, приходят сюда.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym стоит на твоих Garmin. Всё догонит, как только часы будут рядом.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Твои Garmin на месте, но openGym на них ещё нет. Установи его и открой один раз на часах.",
  "Not in reach": "Вне досягаемости",
  "openGym isn’t on it yet": "openGym на них ещё нет",
  "Your Garmins": "Твои Garmin",
  "Choose watches": "Выбрать часы",
  "Look again": "Поискать снова",
  "Get openGym for Garmin": "openGym для Garmin",
  "Start a workout on the phone and your Garmin asks to open openGym.": "Начни тренировку на телефоне, и Garmin предложит открыть openGym.",
  // --- daily form, vitals, month story (gm-insights-146) ---
  "10% lighter": "На 10% легче",
  "About the same": "Примерно так же",
  "After 7 hours of sleep or more": "После 7 часов сна и больше",
  "As planned": "Как по плану",
  "Barely slept": "Почти не спал",
  "Calm": "Спокойно",
  "Check in before workouts?": "Отметиться перед тренировкой?",
  "Could easily be chance": "Вполне может быть случайностью",
  "Daily check-in": "Ежедневная отметка",
  "Daily form": "Форма дня",
  "Energy": "Энергия",
  "Estimated strength": "Оценка силы",
  "Every single week. That is a habit, not a phase.": "Каждую неделю без исключения. Это уже привычка, а не этап.",
  "Every week you showed up counted.": "Каждая неделя, когда ты пришёл, засчитана.",
  "Everything aches": "Болит всё",
  "Exercise of the month": "Упражнение месяца",
  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "Для карточки «Форма дня» в Статистике и твоей отметки. Читается только на этом телефоне и никуда не отправляется.",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Четыре касания про сон, энергию, крепатуру и стресс. В тяжёлый день openGym предложит облегчить тренировку, а через пару недель ты увидишь, что общего у твоих хороших дней.",
  "Frazzled": "На взводе",
  "From Apple Health, read-only, on this phone only.": "Из Apple Health, только чтение, только на этом телефоне.",
  "From Health Connect, read-only, on this phone only.": "Из Health Connect, только чтение, только на этом телефоне.",
  "Full of beans": "Полон сил",
  "HRV (RMSSD)": "ВСР (RMSSD)",
  "HRV (SDNN)": "ВСР (SDNN)",
  "How are you today?": "Как ты сегодня?",
  "How your days and your workouts line up": "Как связаны твои дни и тренировки",
  "Insights show up once there is enough to compare: {0} of {1} workouts so far.": "Выводы появятся, когда будет что сравнивать: пока {0} из {1} тренировок.",
  "Just today. This session sits out of progression, so your next targets stay put.": "Только сегодня. Эта тренировка не учитывается в прогрессии, так что следующие цели остаются на месте.",
