  "Your month in openGym": "Твой месяц в openGym",
  "openGym asks Apple Health for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym запросит у Apple Health твой сон, пульс в покое, вариабельность сердечного ритма и шаги. Разреши то, что хочешь. Данные остаются на этом телефоне, в собственном файле openGym, и никогда не уходят на сервер.",
  "openGym asks Health Connect for your sleep, resting heart rate, heart rate variability and steps. Allow the ones you like. They stay on this phone, in openGym’s own file, and never go to a server.": "openGym запросит у Health Connect твой сон, пульс в покое, вариабельность сердечного ритма и шаги. Разреши то, что хочешь. Данные остаются на этом телефоне, в собственном файле openGym, и никогда не уходят на сервер.",
