  "Badges on your profile": "Значки в профиле",
  "Bodyweight moves from easier to harder. Own every set at the top of the range and the next rung is yours.": "Упражнения с собственным весом от простых к сложным. Сделай каждый подход на верхней границе диапазона, и следующая ступень твоя.",
  "Build a session": "Собрать тренировку",
  "Built from the whole library. Pick a gym in Settings to narrow it.": "Собрано из всей библиотеки. Выбери зал в Настройках, чтобы сузить.",
  "Built from what “{0}” has.": "Собрано из того, что есть в «{0}».",
  "Choose a muscle to see exercises that train it, or build a session from it.": "Выбери мышцу, чтобы увидеть упражнения на неё или собрать из них тренировку.",
  "Cluster": "Кластер",
  "Core ladder": "Лестница кора",
  "Delete ladder": "Удалить лестницу",
  "Deload week: {0} of {1} sets, same weight. Lighter on purpose.": "Разгрузочная неделя: {0} из {1} подходов, тот же вес. Легче специально.",
  "Deload week?": "Разгрузочная неделя?",
