  "Dip ladder": "Лестница отжиманий на брусьях",
  "Dumbbells only": "Только гантели",
  "Easiest first. The Skill ladder rule moves you one rung up when every set hits the top.": "Сначала самое простое. Правило «Лестница навыков» поднимает тебя на ступень, когда каждый подход доходит до верха.",
  "Edit ladder": "Изменить лестницу",
  "Every set at {0}. You’re ready for the next rung.": "Каждый подход на {0}. Ты готов к следующей ступени.",
  "Every set becomes a cluster: {0} reps in mini-sets of {1}, {2}s to breathe between them, same weight throughout. Heavy work with fewer ugly last reps.": "Каждый подход становится кластером: {0} повт. мини-подходами по {1}, {2} с передышки между ними, вес всё время тот же. Тяжёлая работа и меньше корявых последних повторений.",
