  "Every {0} weeks.": "Раз в {0} нед.",
  "Every {0} weeks. Next one: week of {1}.": "Раз в {0} нед. Следующая: неделя с {1}.",
  "Everything you picked is still recovering. Here it is anyway, go easy.": "Всё, что ты выбрал, ещё восстанавливается. Вот тренировка всё равно, только полегче.",
  "Excused": "Уважительная",
  "Fair enough. Asking again next week.": "Справедливо. Спросим снова на следующей неделе.",
  "For bodyweight skills. One more rep each clean session up to the top of the range, then the next, harder variation of the ladder, back at the bottom.": "Для навыков с собственным весом. На одно повторение больше за каждую чистую тренировку до верха диапазона, потом следующий, более сложный вариант из лестницы, снова с низа.",
  "Full week it is.": "Значит, полная неделя.",
