  "Sick or travelling? Mark a day of that week with a day note and the week is excused, no freeze spent (a few times a year).": "Заболел или в поездке? Отметь один день той недели заметкой дня, и неделя засчитана как уважительная, без траты заморозки (несколько раз в год).",
