  "You were injured, so this week is excused. The streak kept going and no freeze was spent.": "У тебя была травма, так что неделя засчитана как уважительная. Серия продолжается, заморозка не потрачена.",
  "You were sick, so this week is excused. The streak kept going and no freeze was spent.": "Ты болел, так что неделя засчитана как уважительная. Серия продолжается, заморозка не потрачена.",
  "You were travelling, so this week is excused. The streak kept going and no freeze was spent.": "Ты был в поездке, так что неделя засчитана как уважительная. Серия продолжается, заморозка не потрачена.",
