  "{0}% fewer sets, same weights. Recharge.": "На {0}% меньше подходов, те же веса. Перезарядка.",
  "{1} are still recovering, so they sit this one out.": {"one":"{1} ещё восстанавливается, так что пропускает эту тренировку.","few":"{1} ещё восстанавливаются, так что пропускают эту тренировку.","many":"{1} ещё восстанавливаются, так что пропускают эту тренировку.","other":"{1} ещё восстанавливаются, так что пропускают эту тренировку."},
  "{1} is still recovering, so it sits this one out.": "{1} ещё восстанавливается, так что в этот раз отдыхает.",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "Так и останется: у openGym Offline нет доступа к интернету, и Android блокирует всё, что он мог бы попробовать.",
  "Any of the sounds on your phone.": "Любой звук с твоего телефона.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "Время от времени делай копию в Настройки, Данные и копия. Файл на телефоне: единственная копия.",
  "Closing the app resets the count; the log never leaves the phone.": "Закрытие приложения обнуляет счётчик; журнал никогда не покидает телефон.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "Считаем с {0}, когда запустилось приложение. Закрытие обнуляет; журнал никогда не покидает телефон.",
  "Each reminder can sound different, so you know which one it is before you look.": "Каждое напоминание может звучать по-своему, и ты узнаешь его, ещё не глядя.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "Всё, что это приложение спрашивало у интернета, новое сверху. Только адрес, никогда содержимое.",
  "For reading mid-set without your glasses.": "Чтобы читать посреди подхода без очков.",
  "Larger": "Ещё крупнее",
  "Last at {0}": "Последний в {0}",
  "Latest": "Последние",
  "Less: no sliding, bouncing or snow. Things just appear.": "Меньше: ничего не скользит, не прыгает и не идёт снег. Всё просто появляется.",
  "Like the phone": "Как в телефоне",
  "Mostly your own server, {0}, when there was something to sync.": "В основном твой собственный сервер, {0}, когда было что синхронизировать.",
  "Motion": "Анимация",
  "Network log": "Журнал сети",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "В openGym Offline нет поиска по карте. Встань в своём зале, нажми «Текущее местоположение», готово.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Ни один байт не покинул этот телефон. Твои тренировки никого, кроме тебя, не касаются.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "Пока ничего. Сервер слышит этот телефон, когда есть что синхронизировать.",
  "Phone default": "Как в телефоне по умолчанию",
  "Phone sound": "Звук телефона",
  "Pick a phone sound…": "Выбрать звук телефона…",
  "Showing the last {0}. The count above has them all.": "Последние {0}. Счётчик выше знает обо всех.",
  "Shows up, keeps quiet.": "Появляется, молчит.",
  "Tap one to hear it. It rings even with the app closed.": "Нажми, чтобы послушать. Звучит и при закрытом приложении.",
  "Text size": "Размер текста",
  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "Это openGym Offline: Android даже не пускает его в интернет. Хочешь синхронизацию? Обычное приложение openGym умеет, рядом с этим.",
  "Weigh-ins, measurements and progress photos.": "Взвешивания, замеры и фото прогресса.",
  "Whatever your phone uses for notifications.": "То, что телефон использует для уведомлений.",
  "When you walk into your gym.": "Когда ты заходишь в свой зал.",
  "Who": "Кто",
  "Who this app talked to since you opened it.": "С кем это приложение общалось с момента открытия.",
  "Workout days and the nudge when one slips by.": "Дни тренировок и толчок, когда одна проскочила.",
  "Workout reminders": "Напоминания о тренировках",
  "openGym Offline has no internet permission. Your training stays on this phone, full stop.": "У openGym Offline нет доступа к интернету. Твои тренировки остаются на этом телефоне, и точка.",
  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline никогда не ищет обновления, он не может. Новые версии там, откуда ты взял эту.",
  "openGym Offline, no internet permission": "openGym Offline, без доступа к интернету",
