  "No set for {0} minutes. If you’re done, I’ll wrap it up in {1} minutes, ending at your last set.": "Подходов нет уже {0} мин. Если закончил, я завершу её через {1} мин, концом будет последний подход.",
  "Looks like you left the gym": "Похоже, ты ушёл из зала",
  "Finish the workout now? Otherwise it ends by itself in {0} minutes.": "Завершить тренировку сейчас? Иначе она завершится сама через {0} мин.",
