  "Finish now": "Завершить сейчас",
  "Finish the workout now? Otherwise it ends by itself at {0}.": "Завершить тренировку сейчас? Иначе она завершится сама в {0}.",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "Давно ничего не записано. Если закончил, она завершится сама в {0}, сохранённая на последнем подходе.",
  "Forgotten workouts": "Забытые тренировки",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Если никто не ответит, она завершится сама и ничего не выбросит. Конец это последний подход плюс его отдых, так время остаётся честным. Открыть её снова можно из истории в течение суток. Часы тоже спрашивают.",
